<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> build_context</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">chunks</span><span style="color:#ABB2BF;">: list[</span><span style="color:#56B6C2;">dict</span><span style="color:#ABB2BF;">]) -&gt; </span><span style="color:#56B6C2;">str</span><span style="color:#ABB2BF;">:</span></span>
