<span class="line"><span style="color:#C678DD;">async</span><span style="color:#C678DD;"> def</span><span style="color:#61AFEF;"> reindex</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">request</span><span style="color:#ABB2BF;">: Request):</span></span>
